1	package jadx.core.xmlgen;
2	
3	import java.nio.ByteBuffer;
4	import java.nio.ByteOrder;
5	import java.util.Arrays;
6	import java.util.HashMap;
7	import java.util.Map;
8	
9	public class BinaryXMLStrings {
10		public static final String INVALID_STRING_PLACEHOLDER = "⟨STRING_DECODE_ERROR⟩";
11		private final int stringCount;
12	
13		private final long stringsStart;
14	
15		private final ByteBuffer buffer;
16	
17		private final boolean isUtf8;
18	
19		// This cache include strings that have been overridden by the deobfuscator.
20		private final Map<Integer, String> cache = new HashMap<>();
21	
22		public BinaryXMLStrings() {
23			stringCount = 0;
24			stringsStart = 0;
25			buffer = ByteBuffer.allocate(0);
26			buffer.order(ByteOrder.LITTLE_ENDIAN);
27			isUtf8 = false;
28		}
29	
30		public BinaryXMLStrings(int stringCount, long stringsStart, byte[] buffer, boolean isUtf8) {
31			this.stringCount = stringCount;
32			this.stringsStart = stringsStart;
33			this.buffer = ByteBuffer.wrap(buffer);
34			this.buffer.order(ByteOrder.LITTLE_ENDIAN);
35			this.isUtf8 = isUtf8;
36		}
37	
38		public String get(int id) {
39			String cached = cache.get(id);
40			if (cached != null) {
41				return cached;
42			}
43	
44			if (id < 0 || id >= stringCount) {
45				return INVALID_STRING_PLACEHOLDER;
46			}
47	
48			int off = buffer.getInt(id * 4);
49			if (off < 0) {
50				// read unsigned offset value is larger than Integer.MAX_VALUE
51				// In reality this should only happen in obfuscated APKs with invalid offsets
52				return INVALID_STRING_PLACEHOLDER;
53			}
54			long offset = stringsStart + off;
55			String extracted;
56			if (isUtf8) {
57				extracted = extractString8(this.buffer.array(), (int) offset);
58			} else {
59				// don't trust specified string length, read until \0
60				// stringsOffset can be same for different indexes
61				extracted = extractString16(this.buffer.array(), (int) offset);
62			}
63			cache.put(id, extracted);
64			return extracted;
65		}
66	
67		public void put(int id, String content) {
68			cache.put(id, content);
69		}
70	
71		public int size() {
72			return this.stringCount;
73		}
74	
75		private static String extractString8(byte[] strArray, int offset) {
76			if (offset >= strArray.length) {
77				return INVALID_STRING_PLACEHOLDER;
78			}
79			int start = offset + skipStrLen8(strArray, offset);
80			if (start >= strArray.length) {
81				return INVALID_STRING_PLACEHOLDER;
82			}
83			int len = strArray[start++];
84			if (len == 0) {
85				return "";
86			}
87			if ((len & 0x80) != 0) {
88				len = (len & 0x7F) << 8 | strArray[start++] & 0xFF;
89			}
90			byte[] arr = Arrays.copyOfRange(strArray, start, start + len);
91			return new String(arr, ParserStream.STRING_CHARSET_UTF8);
92		}
93	
94		private static String extractString16(byte[] strArray, int offset) {
95			if (offset + 2 >= strArray.length) {
96				return INVALID_STRING_PLACEHOLDER;
97			}
98	
99			int len = strArray.length;
100			int start = offset + skipStrLen16(strArray, offset);
101			int end = start;
102			while (true) {
103				if (end + 1 >= len) {
104					break;
105				}
106				if (strArray[end] == 0 && strArray[end + 1] == 0) {
107					break;
108				}
109				end += 2;
110			}
111			byte[] arr = Arrays.copyOfRange(strArray, start, end);
112			return new String(arr, ParserStream.STRING_CHARSET_UTF16);
113		}
114	
115		private static int skipStrLen8(byte[] strArray, int offset) {
116			return (strArray[offset] & 0x80) == 0 ? 1 : 2;
117		}
118	
119		private static int skipStrLen16(byte[] strArray, int offset) {
120			return (strArray[offset + 1] & 0x80) == 0 ? 2 : 4;
121		}
122	}
