1	package jadx.core.xmlgen;
2	
3	import java.io.IOException;
4	import java.io.InputStream;
5	import java.util.HashMap;
6	import java.util.HashSet;
7	import java.util.Map;
8	import java.util.Random;
9	import java.util.Set;
10	
11	import org.jetbrains.annotations.Nullable;
12	import org.slf4j.Logger;
13	import org.slf4j.LoggerFactory;
14	
15	import jadx.api.ICodeInfo;
16	import jadx.api.ICodeWriter;
17	import jadx.api.ResourcesLoader;
18	import jadx.core.dex.info.ConstStorage;
19	import jadx.core.dex.nodes.ClassNode;
20	import jadx.core.dex.nodes.RootNode;
21	import jadx.core.utils.StringUtils;
22	import jadx.core.utils.android.AndroidResourcesMap;
23	import jadx.core.utils.exceptions.JadxRuntimeException;
24	import jadx.core.xmlgen.entry.ValuesParser;
25	
26	public class BinaryXMLParser extends CommonBinaryParser {
27		private static final Logger LOG = LoggerFactory.getLogger(BinaryXMLParser.class);
28	
29		private final RootNode rootNode;
30		private final ManifestAttributes manifestAttributes;
31		private final boolean attrNewLine;
32	
33		private final Map<Integer, String> resNames;
34		private Map<String, String> nsMap;
35		private Set<String> nsMapGenerated;
36		private Set<String> definedNamespaces;
37		private final Map<String, String> tagAttrDeobfNames = new HashMap<>();
38	
39		private ICodeWriter writer;
40		private BinaryXMLStrings strings;
41		private String currentTag = "ERROR";
42		private boolean firstElement;
43		private ValuesParser valuesParser;
44		private boolean isLastEnd = true;
45		private boolean isOneLine = true;
46		private int namespaceDepth = 0;
47		private @Nullable int[] resourceIds;
48		private String appPackageName;
49	
50		private Map<String, ClassNode> classNameCache;
51	
52		public BinaryXMLParser(RootNode rootNode) {
53			this.rootNode = rootNode;
54			this.manifestAttributes = rootNode.initManifestAttributes();
55			this.attrNewLine = !rootNode.getArgs().isSkipXmlPrettyPrint();
56			try {
57				ConstStorage constStorage = rootNode.getConstValues();
58				resNames = constStorage.getResourcesNames();
59			} catch (Exception e) {
60				throw new JadxRuntimeException("BinaryXMLParser init error", e);
61			}
62		}
63	
64		public synchronized ICodeInfo parse(InputStream inputStream) throws IOException {
65			resourceIds = null;
66			is = new ParserStream(inputStream);
67			if (!isBinaryXml()) {
68				return ResourcesLoader.loadToCodeWriter(is);
69			}
70			nsMapGenerated = new HashSet<>();
71			nsMap = new HashMap<>();
72			definedNamespaces = new HashSet<>();
73			writer = rootNode.makeCodeWriter();
74			writer.add("<?xml version=\"1.0\" encoding=\"utf-8\"?>");
75			firstElement = true;
76			decode();
77			nsMap = null;
78			definedNamespaces = null;
79			ICodeInfo codeInfo = writer.finish();
80			this.classNameCache = null; // reset class name cache
81			return codeInfo;
82		}
83	
84		private boolean isBinaryXml() throws IOException {
85			is.mark(4);
86			int v = is.readInt16(); // version
87			int h = is.readInt16(); // header size
88			// Some APK Manifest.xml the version is 0
89			if (h == 0x0008) {
90				return true;
91			}
92			is.reset();
93			return false;
94		}
95	
96		void decode() throws IOException {
97			int size = is.readInt32();
98			while (is.getPos() < size) {
99				int type = is.readInt16();
100				switch (type) {
101					case RES_NULL_TYPE:
102						// NullType is just doing nothing
103						break;
104					case RES_STRING_POOL_TYPE:
105						strings = parseStringPoolNoType();
106						valuesParser = new ValuesParser(strings, resNames);
107						break;
108					case RES_XML_RESOURCE_MAP_TYPE:
109						parseResourceMap();
110						break;
111					case RES_XML_START_NAMESPACE_TYPE:
112						parseNameSpace();
113						break;
114					case RES_XML_CDATA_TYPE:
115						parseCData();
116						break;
117					case RES_XML_END_NAMESPACE_TYPE:
118						parseNameSpaceEnd();
119						break;
120					case RES_XML_START_ELEMENT_TYPE:
121						parseElement();
122						break;
123					case RES_XML_END_ELEMENT_TYPE:
124						parseElementEnd();
125						break;
126	
127					default:
128						if (namespaceDepth == 0) {
129							// skip padding on file end
130							return;
131						}
132						die("Type: 0x" + Integer.toHexString(type) + " not yet implemented");
133						break;
134				}
135			}
136		}
137	
138		private void parseResourceMap() throws IOException {
139			if (is.readInt16() != 0x8) {
140				die("Header size of resmap is not 8!");
141			}
142			int size = is.readInt32();
143			int len = (size - 8) / 4;
144			resourceIds = new int[len];
145			for (int i = 0; i < len; i++) {
146				resourceIds[i] = is.readInt32();
147			}
148		}
149	
150		private void parseNameSpace() throws IOException {
151			int headerSize = is.readInt16();
152			if (headerSize > 0x10) {
153				LOG.warn("Invalid namespace header");
154			} else if (headerSize < 0x10) {
155				die("NAMESPACE header is not 0x10 big");
156			}
157			int size = is.readInt32();
158			if (size > 0x18) {
159				LOG.warn("Invalid namespace size");
160			} else if (size < 0x18) {
161				die("NAMESPACE header chunk is not 0x18 big");
162			}
163	
164			int beginLineNumber = is.readInt32();
165			int comment = is.readInt32();
166			int beginPrefix = is.readInt32();
167			int beginURI = is.readInt32();
168			is.skip(headerSize - 0x10);
169	
170			String nsKey = getString(beginURI);
171			String nsValue = getString(beginPrefix);
172			if (StringUtils.notBlank(nsKey) && !nsMap.containsValue(nsValue)) {
173				nsMap.putIfAbsent(nsKey, nsValue);
174			}
175			namespaceDepth++;
176		}
177	
178		private void parseNameSpaceEnd() throws IOException {
179			int headerSize = is.readInt16();
180			if (headerSize > 0x10) {
181				LOG.warn("Invalid namespace end");
182			} else if (headerSize < 0x10) {
183				die("NAMESPACE end is not 0x10 big");
184			}
185			int dataSize = is.readInt32();
186			if (dataSize != 0x18) {
187				LOG.warn("Invalid namespace end size");
188			}
189			int endLineNumber = is.readInt32();
190			int comment = is.readInt32();
191			int endPrefix = is.readInt32();
192			int endURI = is.readInt32();
193			is.skip(headerSize - 0x10);
194			namespaceDepth--;
195	
196			String nsKey = getString(endURI);
197			String nsValue = getString(endPrefix);
198			if (StringUtils.notBlank(nsKey) && !nsMap.containsValue(nsValue)) {
199				nsMap.putIfAbsent(nsKey, nsValue);
200			}
201		}
202	
203		private void parseCData() throws IOException {
204			if (is.readInt16() != 0x10) {
205				die("CDATA header is not 0x10");
206			}
207			if (is.readInt32() != 0x1C) {
208				die("CDATA header chunk is not 0x1C");
209			}
210			int lineNumber = is.readInt32();
211			is.skip(4);
212	
213			int strIndex = is.readInt32();
214			String str = getString(strIndex);
215			if (!isLastEnd) {
216				isLastEnd = true;
217				writer.add('>');
218			}
219			writer.attachSourceLine(lineNumber);
220			String escapedStr = StringUtils.escapeXML(str);
221			writer.add(escapedStr);
222	
223			long size = is.readInt16();
224			is.skip(size - 2);
225		}
226	
227		private void parseElement() throws IOException {
228			if (firstElement) {
229				firstElement = false;
230			} else {
231				writer.incIndent();
232			}
233			if (is.readInt16() != 0x10) {
234				die("ELEMENT HEADER SIZE is not 0x10");
235			}
236			// TODO: Check element chunk size
237			long startPos = is.getPos();
238			int elementSize = is.readInt32();
239			int elementBegLineNumber = is.readInt32();
240			int comment = is.readInt32();
241			int startNS = is.readInt32();
242			int startNSName = is.readInt32(); // actually is elementName...
243			if (!isLastEnd && !"ERROR".equals(currentTag)) {
244				writer.add('>');
245			}
246			isOneLine = true;
247			isLastEnd = false;
248			currentTag = deobfClassName(getString(startNSName));
249			currentTag = getValidTagAttributeName(currentTag);
250			writer.startLine('<').add(currentTag);
251			writer.attachSourceLine(elementBegLineNumber);
252			int attributeStart = is.readInt16();
253			if (attributeStart != 0x14) {
254				die("startNS's attributeStart is not 0x14");
255			}
256			int attributeSize = is.readInt16();
257			if (attributeSize < 0x14) {
258				die("startNS's attributeSize is less than 0x14");
259			}
260	
261			int attributeCount = is.readInt16();
262			int idIndex = is.readInt16();
263			int classIndex = is.readInt16();
264			int styleIndex = is.readInt16();
265			if ("manifest".equals(currentTag) || definedNamespaces.size() != nsMap.size()) {
266				for (Map.Entry<String, String> entry : nsMap.entrySet()) {
267					if (!definedNamespaces.contains(entry.getKey())) {
268						definedNamespaces.add(entry.getKey());
269						String nsValue = getValidTagAttributeName(entry.getValue());
270						writer.add(" xmlns");
271						if (nsValue != null && !nsValue.trim().isEmpty()) {
272							writer.add(':');
273							writer.add(nsValue);
274						}
275						writer.add("=\"").add(StringUtils.escapeXML(entry.getKey())).add('"');
276					}
277				}
278			}
279			Set<String> attrCache = new HashSet<>();
280			boolean attrNewLine = attributeCount != 1 && this.attrNewLine;
281			for (int i = 0; i < attributeCount; i++) {
282				parseAttribute(i, attrNewLine, attrCache, attributeSize);
283			}
284			long endPos = is.getPos();
285			if (endPos - startPos + 0x4 < elementSize) {
286				is.skip(elementSize - (endPos - startPos + 0x4));
287			}
288		}
289	
290		private void parseAttribute(int i, boolean newLine, Set<String> attrCache, int attributeSize) throws IOException {
291			int attributeNS = is.readInt32();
292			int attributeName = is.readInt32();
293			int attributeRawValue = is.readInt32();
294			is.skip(3);
295			int attrValDataType = is.readInt8();
296			int attrValData = is.readInt32();
297	
298			is.skip(attributeSize - 0x14);
299	
300			String shortNsName = null;
301			if (attributeNS != -1) {
302				shortNsName = getAttributeNS(attributeNS, newLine);
303			}
304			String attrName = getValidTagAttributeName(getAttributeName(attributeName));
305			String attrFullName = shortNsName != null ? shortNsName + ":" + attrName : attrName;
306			// do not dump duplicated values
307			if (XmlDeobf.isDuplicatedAttr(attrFullName, attrCache)) {
308				return;
309			}
310	
311			if (newLine) {
312				writer.startLine().addIndent();
313			} else {
314				writer.add(' ');
315			}
316			writer.add(attrFullName).add("=\"");
317			String decodedAttr = manifestAttributes.decode(attrFullName, attrValData);
318			if (decodedAttr != null) {
319				memorizePackageName(attrName, decodedAttr);
320				if (isDeobfCandidateAttr(attrFullName)) {
321					decodedAttr = deobfClassName(decodedAttr);
322				}
323				attachClassNode(writer, attrName, decodedAttr);
324				writer.add(StringUtils.escapeXML(decodedAttr));
325			} else {
326				decodeAttribute(attributeNS, attrValDataType, attrValData,
327						attrFullName);
328			}
329			if (shortNsName != null && shortNsName.equals("android")) {
330				if (attrName.equals("pathData")) {
331					rootNode.getGradleInfoStorage().setVectorPathData(true);
332				} else if (attrName.equals("fillType")) {
333					rootNode.getGradleInfoStorage().setVectorFillType(true);
334				}
335			}
336			writer.add('"');
337		}
338	
339		private String getAttributeNS(int attributeNS, boolean newLine) {
340			String attrUrl = getString(attributeNS);
341			if (attrUrl == null || attrUrl.isEmpty()) {
342				if (isResInternalId(attributeNS)) {
343					return null;
344				} else {
345					attrUrl = ANDROID_NS_URL;
346				}
347			}
348			String attrName = nsMap.get(attrUrl);
349			if (attrName == null) {
350				attrName = generateNameForNS(attrUrl, newLine);
351			}
352			return attrName;
353		}
354	
355		private String generateNameForNS(String attrUrl, boolean newLine) {
356			String attrName;
357			if (ANDROID_NS_URL.equals(attrUrl)) {
358				attrName = ANDROID_NS_VALUE;
359				nsMap.put(ANDROID_NS_URL, attrName);
360			} else {
361				for (int i = 1;; i++) {
362					attrName = "ns" + i;
363					if (!nsMapGenerated.contains(attrName) && !nsMap.containsValue(attrName)) {
364						nsMapGenerated.add(attrName);
365						// do not add generated value to nsMap
366						// because attrUrl might be used in a neighbor element, but never defined
367						break;
368					}
369				}
370			}
371			if (newLine) {
372				writer.startLine().addIndent();
373			} else {
374				writer.add(' ');
375			}
376			writer.add("xmlns:").add(attrName).add("=\"").add(attrUrl).add("\" ");
377			return attrName;
378		}
379	
380		private String getAttributeName(int id) {
381			// As the outcome of https://github.com/skylot/jadx/issues/1208
382			// Android seems to favor entries from AndroidResMap and only if
383			// there is no entry uses the values form the XML string pool
384			if (resourceIds != null && 0 <= id && id < resourceIds.length) {
385				int resId = resourceIds[id];
386				String str = AndroidResourcesMap.getResName(resId);
387				if (str != null) {
388					// cut type before /
389					int typeEnd = str.indexOf('/');
390					if (typeEnd != -1) {
391						return str.substring(typeEnd + 1);
392					}
393					return str;
394				}
395			}
396	
397			String str = getString(id);
398			if (str == null || str.isEmpty()) {
399				return "NOT_FOUND_0x" + Integer.toHexString(id);
400			}
401			return str;
402		}
403	
404		private String getString(int strId) {
405			if (0 <= strId && strId < strings.size()) {
406				return strings.get(strId);
407			}
408			return "NOT_FOUND_STR_0x" + Integer.toHexString(strId);
409		}
410	
411		private void decodeAttribute(int attributeNS, int attrValDataType, int attrValData, String attrFullName) {
412			if (attrValDataType == TYPE_REFERENCE) {
413				// reference custom processing
414				String resName = resNames.get(attrValData);
415				if (resName != null) {
416					writer.add('@');
417					if (resName.startsWith("id/")) {
418						writer.add('+');
419					}
420					writer.add(resName);
421				} else {
422					String androidResName = AndroidResourcesMap.getResName(attrValData);
423					if (androidResName != null) {
424						writer.add("@android:").add(androidResName);
425					} else if (attrValData == 0) {
426						writer.add("@null");
427					} else {
428						writer.add("0x").add(Integer.toHexString(attrValData));
429					}
430				}
431			} else {
432				String str;
433				try {
434					str = valuesParser.decodeValue(attrValDataType, attrValData);
435				} catch (JadxRuntimeException e) {
436					LOG.error("Failed to decode attribute value of \"{}\"", attrFullName, e);
437					str = null;
438				}
439				memorizePackageName(attrFullName, str);
440				if (isDeobfCandidateAttr(attrFullName)) {
441					str = deobfClassName(str);
442				}
443				attachClassNode(writer, attrFullName, str);
444				writer.add(str != null ? StringUtils.escapeXML(str) : "null");
445			}
446		}
447	
448		private void parseElementEnd() throws IOException {
449			if (is.readInt16() != 0x10) {
450				die("ELEMENT END header is not 0x10");
451			}
452			if (is.readInt32() != 0x18) {
453				die("ELEMENT END header chunk is not 0x18 big");
454			}
455			int endLineNumber = is.readInt32();
456			int comment = is.readInt32();
457			int elementNS = is.readInt32();
458			int elementNameId = is.readInt32();
459			String elemName = deobfClassName(getString(elementNameId));
460			elemName = getValidTagAttributeName(elemName);
461			if (currentTag.equals(elemName) && isOneLine && !isLastEnd) {
462				writer.add("/>");
463			} else {
464				writer.startLine("</");
465				writer.attachSourceLine(endLineNumber);
466				// if (elementNS != -1) {
467				// writer.add(getString(elementNS)).add(':');
468				// }
469				writer.add(elemName).add('>');
470			}
471			isLastEnd = true;
472			if (writer.getIndent() != 0) {
473				writer.decIndent();
474			}
475		}
476	
477		private String getValidTagAttributeName(String originalName) {
478			if (XMLChar.isValidName(originalName)) {
479				return originalName;
480			}
481			if (tagAttrDeobfNames.containsKey(originalName)) {
482				return tagAttrDeobfNames.get(originalName);
483			}
484			String generated;
485			do {
486				generated = generateTagAttrName();
487			} while (tagAttrDeobfNames.containsValue(generated));
488			tagAttrDeobfNames.put(originalName, generated);
489			return generated;
490		}
491	
492		private static String generateTagAttrName() {
493			final int length = 6;
494			Random r = new Random();
495			StringBuilder sb = new StringBuilder();
496			for (int i = 1; i <= length; i++) {
497				sb.append((char) (r.nextInt(26) + 'a'));
498			}
499			return sb.toString();
500		}
501	
502		private void attachClassNode(ICodeWriter writer, String attrFullName, String clsName) {
503			if (!writer.isMetadataSupported()) {
504				return;
505			}
506			if (clsName == null || !attrFullName.equals("android:name")) {
507				return;
508			}
509			String clsFullName;
510			if (clsName.startsWith(".")) {
511				clsFullName = appPackageName + clsName;
512			} else {
513				clsFullName = clsName;
514			}
515			if (classNameCache == null) {
516				classNameCache = rootNode.buildFullAliasClassCache();
517			}
518			ClassNode classNode = classNameCache.get(clsFullName);
519			if (classNode != null) {
520				writer.attachAnnotation(classNode);
521			}
522		}
523	
524		private String deobfClassName(String className) {
