7	import java.nio.charset.Charset;
8	import java.nio.charset.StandardCharsets;
9	
10	import org.jetbrains.annotations.NotNull;
11	
12	public class ParserStream extends InputStream {
13	
14		protected static final Charset STRING_CHARSET_UTF16 = StandardCharsets.UTF_16LE;
15		protected static final Charset STRING_CHARSET_UTF8 = StandardCharsets.UTF_8;
16	
17		private static final int[] EMPTY_INT_ARRAY = new int[0];
18		private static final byte[] EMPTY_BYTE_ARRAY = new byte[0];
19	
20		private final InputStream input;
21		private long readPos = 0;
22		private long markPos = 0;
23	
24		public ParserStream(@NotNull InputStream inputStream) {
25			this.input = inputStream.markSupported() ? inputStream : new BufferedInputStream(inputStream);
26		}
27	
28		public long getPos() {
29			return readPos;
30		}
31	
32		public int readInt8() throws IOException {
33			readPos++;
34			return input.read();
35		}
36	
37		public int readInt16() throws IOException {
38			readPos += 2;
39			int b1 = input.read();
40			int b2 = input.read();
41			return (b2 & 0xFF) << 8 | b1 & 0xFF;
42		}
43	
44		public int readInt32() throws IOException {
45			readPos += 4;
46			InputStream in = input;
47			int b1 = in.read();
48			int b2 = in.read();
49			int b3 = in.read();
50			int b4 = in.read();
51			return b4 << 24 | (b3 & 0xFF) << 16 | (b2 & 0xFF) << 8 | b1 & 0xFF;
52		}
53	
54		public long readUInt32() throws IOException {
55			return readInt32() & 0xFFFFFFFFL;
56		}
57	
58		public String readString16Fixed(int len) throws IOException {
59			String str = new String(readInt8Array(len * 2), STRING_CHARSET_UTF16);
60			return str.trim();
61		}
62	
63		public int[] readInt32Array(int count) throws IOException {
64			if (count == 0) {
65				return EMPTY_INT_ARRAY;
66			}
67			int[] arr = new int[count];
68			for (int i = 0; i < count; i++) {
69				arr[i] = readInt32();
70			}
71			return arr;
72		}
73	
74		public byte[] readInt8Array(int count) throws IOException {
75			if (count == 0) {
76				return EMPTY_BYTE_ARRAY;
77			}
78			readPos += count;
79			byte[] arr = new byte[count];
80			int pos = input.read(arr, 0, count);
81			while (pos < count) {
82				int read = input.read(arr, pos, count - pos);
83				if (read == -1) {
84					throw new IOException("No data, can't read " + count + " bytes");
85				}
86				pos += read;
87			}
88			return arr;
89		}
90	
91		@Override
92		public long skip(long count) throws IOException {
93			readPos += count;
94			long pos = input.skip(count);
95			while (pos < count) {
96				long skipped = input.skip(count - pos);
97				if (skipped == 0) {
98					throw new IOException("No data, can't skip " + count + " bytes");
99				}
100				pos += skipped;
101			}
102			return pos;
103		}
104	
105		public void checkInt8(int expected, String error) throws IOException {
106			int v = readInt8();
107			if (v != expected) {
108				throwException(error, expected, v);
109			}
110		}
111	
112		public void checkInt16(int expected, String error) throws IOException {
113			int v = readInt16();
114			if (v != expected) {
115				throwException(error, expected, v);
116			}
117		}
118	
119		private void throwException(String error, int expected, int actual) throws IOException {
120			throw new IOException(error
121					+ ", expected: 0x" + Integer.toHexString(expected)
122					+ ", actual: 0x" + Integer.toHexString(actual)
123					+ ", offset: 0x" + Long.toHexString(getPos()));
124		}
125	
126		public void checkPos(long expectedOffset, String error) throws IOException {
127			if (getPos() != expectedOffset) {
128				throw new IOException(error + ", expected offset: 0x" + Long.toHexString(expectedOffset)
129						+ ", actual: 0x" + Long.toHexString(getPos()));
130			}
131		}
132	
133		public void skipToPos(long expectedOffset, String error) throws IOException {
134			long pos = getPos();
135			if (pos > expectedOffset) {
136				throw new IOException(error + ", expected offset not reachable: 0x" + Long.toHexString(expectedOffset)
137						+ ", actual: 0x" + Long.toHexString(getPos()));
138			}
139			if (pos < expectedOffset) {
140				skip(expectedOffset - pos);
141			}
142			checkPos(expectedOffset, error);
143		}
144	
145		@Override
146		public void mark(int len) {
147			if (!input.markSupported()) {
148				throw new RuntimeException("Mark not supported for input stream " + input.getClass());
149			}
150			input.mark(len);
151			markPos = readPos;
152		}
153	
154		public void mark(long len) {
155			mark((int) Math.min(len, Integer.MAX_VALUE));
156		}
157	
158		@Override
159		public void reset() throws IOException {
160			input.reset();
161			readPos = markPos;
162		}
163	
164		public void readFully(byte[] b) throws IOException {
165			readFully(b, 0, b.length);
166		}
167	
168		public void readFully(byte[] b, int off, int len) throws IOException {
169			readPos += len;
170			if (len < 0) {
171				throw new IndexOutOfBoundsException();
172			}
173			int n = 0;
174			while (n < len) {
175				int count = input.read(b, off + n, len - n);
176				if (count < 0) {
177					throw new EOFException();
178				}
179				n += count;
180			}
181		}
182	
183		@Override
184		public int read() throws IOException {
185			return input.read();
186		}
187	
188		@Override
189		public int read(@NotNull byte[] b, int off, int len) throws IOException {
190			return input.read(b, off, len);
191		}
192	
193		@Override
194		public String toString() {
195			return "pos: 0x" + Long.toHexString(readPos);
196		}
197	}
