1	package jadx.core.utils;
2	
3	import java.util.ArrayList;
4	import java.util.Collections;
5	import java.util.Comparator;
6	import java.util.HashSet;
7	import java.util.List;
8	import java.util.Set;
9	import java.util.stream.Collectors;
10	
11	import org.jetbrains.annotations.NotNull;
12	import org.slf4j.Logger;
13	import org.slf4j.LoggerFactory;
14	
15	import jadx.api.IDecompileScheduler;
16	import jadx.api.JavaClass;
17	import jadx.core.utils.exceptions.JadxRuntimeException;
18	
19	public class DecompilerScheduler implements IDecompileScheduler {
20		private static final Logger LOG = LoggerFactory.getLogger(DecompilerScheduler.class);
21	
22		private static final int MERGED_BATCH_SIZE = 16;
23		private static final boolean DEBUG_BATCHES = false;
24	
25		@Override
26		public List<List<JavaClass>> buildBatches(List<JavaClass> classes) {
27			try {
28				long start = System.currentTimeMillis();
29				List<List<JavaClass>> result = internalBatches(classes);
30				if (LOG.isDebugEnabled()) {
31					LOG.debug("Build decompilation batches in {}ms for {} classes",
32							System.currentTimeMillis() - start, classes.size());
33				}
34				if (DEBUG_BATCHES) {
35					check(result, classes);
36				}
37				return result;
38			} catch (StackOverflowError | BootstrapMethodError e) {
39				LOG.warn("Stack overflow while building decompile batches, continue with fallback");
40			} catch (Exception e) {
41				LOG.warn("Build batches failed (continue with fallback)", e);
42			}
43			return buildFallback(classes);
44		}
45	
46		/**
47		 * Put classes with many dependencies at the end.
48		 * Build batches for dependencies of single class to avoid locking from another thread.
49		 */
50		public List<List<JavaClass>> internalBatches(List<JavaClass> classes) {
51			List<DepInfo> deps = sumDependencies(classes);
52			Set<JavaClass> added = new HashSet<>(classes.size());
53			Comparator<JavaClass> cmpDepSize = Comparator.comparingInt(JavaClass::getTotalDepsCount);
54			List<List<JavaClass>> result = new ArrayList<>();
55			List<JavaClass> mergedBatch = new ArrayList<>(MERGED_BATCH_SIZE);
56			for (DepInfo depInfo : deps) {
57				JavaClass cls = depInfo.getCls();
58				if (!added.add(cls)) {
59					continue;
60				}
61				int depsSize = cls.getTotalDepsCount();
62				if (depsSize == 0) {
63					// add classes without dependencies in merged batch
64					mergedBatch.add(cls);
65					if (mergedBatch.size() >= MERGED_BATCH_SIZE) {
66						result.add(mergedBatch);
67						mergedBatch = new ArrayList<>(MERGED_BATCH_SIZE);
68					}
69				} else {
70					List<JavaClass> batch = new ArrayList<>();
71					for (JavaClass dep : cls.getDependencies()) {
72						JavaClass topDep = dep.getTopParentClass();
73						if (!added.contains(topDep)) {
74							batch.add(topDep);
75							added.add(topDep);
76						}
77					}
78					batch.sort(cmpDepSize);
79					batch.add(cls);
80					result.add(Utils.lockList(batch));
81				}
82			}
83			if (!mergedBatch.isEmpty()) {
84				result.add(Utils.lockList(mergedBatch));
85			}
86			if (DEBUG_BATCHES) {
87				dumpBatchesStats(classes, result, deps);
88			}
89			return result;
90		}
91	
92		private static List<DepInfo> sumDependencies(List<JavaClass> classes) {
93			List<DepInfo> deps = new ArrayList<>(classes.size());
94			for (JavaClass cls : classes) {
95				int count = 0;
96				for (JavaClass dep : cls.getDependencies()) {
97					count += 1 + dep.getTotalDepsCount();
98				}
99				deps.add(new DepInfo(cls, count));
100			}
101			Collections.sort(deps);
102			return deps;
103		}
104	
105		private static final class DepInfo implements Comparable<DepInfo> {
106			private final JavaClass cls;
107			private final int depsCount;
108	
109			private DepInfo(JavaClass cls, int depsCount) {
110				this.cls = cls;
111				this.depsCount = depsCount;
112			}
113	
114			public JavaClass getCls() {
115				return cls;
116			}
117	
118			public int getDepsCount() {
119				return depsCount;
120			}
121	
122			@Override
123			public int compareTo(@NotNull DecompilerScheduler.DepInfo o) {
124				int deps = Integer.compare(depsCount, o.depsCount);
125				if (deps == 0) {
126					return cls.getClassNode().compareTo(o.cls.getClassNode());
127				}
128				return deps;
129			}
130	
131			@Override
132			public String toString() {
133				return cls + ":" + depsCount;
134			}
135		}
136	
137		private static List<List<JavaClass>> buildFallback(List<JavaClass> classes) {
138			return classes.stream()
139					.sorted(Comparator.comparingInt(c -> c.getClassNode().getTotalDepsCount()))
140					.map(Collections::singletonList)
141					.collect(Collectors.toList());
142		}
143	
144		private void dumpBatchesStats(List<JavaClass> classes, List<List<JavaClass>> result, List<DepInfo> deps) {
145			int clsInBatches = result.stream().mapToInt(List::size).sum();
146			double avg = result.stream().mapToInt(List::size).average().orElse(-1);
147			int maxSingleDeps = classes.stream().mapToInt(JavaClass::getTotalDepsCount).max().orElse(-1);
148			int maxSubDeps = deps.stream().mapToInt(DepInfo::getDepsCount).max().orElse(-1);
149			LOG.info("Batches stats:"
150					+ "\n input classes: " + classes.size()
151					+ ",\n classes in batches: " + clsInBatches
152					+ ",\n batches: " + result.size()
153					+ ",\n average batch size: " + String.format("%.2f", avg)
154					+ ",\n max single deps count: " + maxSingleDeps
155					+ ",\n max sub deps count: " + maxSubDeps);
156		}
157	
158		private static void check(List<List<JavaClass>> result, List<JavaClass> classes) {
159			int classInBatches = result.stream().mapToInt(List::size).sum();
160			if (classes.size() != classInBatches) {
161				throw new JadxRuntimeException(
162						"Incorrect number of classes in result batch: " + classInBatches + ", expected: " + classes.size());
163			}
164		}
165	}
