34		/**
35		 * Return constant literal from {@code jadx.api.plugins.input.data.annotations.EncodedValue}
36		 *
37		 * @return LiteralArg, String, ArgType or null
38		 */
39		@Nullable
40		public static Object convertToConstValue(EncodedValue encodedValue) {
41			if (encodedValue == null) {
42				return null;
43			}
44			Object value = encodedValue.getValue();
45			switch (encodedValue.getType()) {
46				case ENCODED_NULL:
47					return InsnArg.lit(0, ArgType.OBJECT);
48				case ENCODED_BOOLEAN:
49					return Boolean.TRUE.equals(value) ? LiteralArg.litTrue() : LiteralArg.litFalse();
50				case ENCODED_BYTE:
51					return InsnArg.lit((Byte) value, ArgType.BYTE);
52				case ENCODED_SHORT:
53					return InsnArg.lit((Short) value, ArgType.SHORT);
54				case ENCODED_CHAR:
55					return InsnArg.lit((Character) value, ArgType.CHAR);
56				case ENCODED_INT:
57					return InsnArg.lit((Integer) value, ArgType.INT);
58				case ENCODED_LONG:
59					return InsnArg.lit((Long) value, ArgType.LONG);
60				case ENCODED_FLOAT:
61					return InsnArg.lit(Float.floatToIntBits((Float) value), ArgType.FLOAT);
62				case ENCODED_DOUBLE:
63					return InsnArg.lit(Double.doubleToLongBits((Double) value), ArgType.DOUBLE);
64				case ENCODED_STRING:
65					// noinspection RedundantCast
66					return (String) value;
67	
68				case ENCODED_TYPE:
69					return ArgType.parse((String) value);
70	
71				default:
72					return null;
73			}
74		}
75	
76		public static InsnArg convertToInsnArg(RootNode root, EncodedValue value) {
77			Object obj = value.getValue();
78			switch (value.getType()) {
79				case ENCODED_NULL:
80				case ENCODED_BYTE:
81				case ENCODED_SHORT:
82				case ENCODED_CHAR:
83				case ENCODED_INT:
84				case ENCODED_LONG:
85				case ENCODED_FLOAT:
86				case ENCODED_DOUBLE:
87					return (InsnArg) convertToConstValue(value);
88	
89				case ENCODED_BOOLEAN:
90					return Boolean.TRUE.equals(obj) ? LiteralArg.litTrue() : LiteralArg.litFalse();
91				case ENCODED_STRING:
92					return InsnArg.wrapArg(new ConstStringNode((String) obj));
93				case ENCODED_TYPE:
94					return InsnArg.wrapArg(new ConstClassNode(ArgType.parse((String) obj)));
95				case ENCODED_METHOD_TYPE:
96					return InsnArg.wrapArg(buildMethodType(root, (IMethodProto) obj));
97				case ENCODED_METHOD_HANDLE:
98					return InsnArg.wrapArg(buildMethodHandle(root, (IMethodHandle) obj));
99	
100			}
101			throw new JadxRuntimeException("Unsupported type for raw invoke-custom: " + value.getType());
102		}
