104		private static InvokeNode buildMethodType(RootNode root, IMethodProto methodProto) {
105			ArgType retType = ArgType.parse(methodProto.getReturnType());
106			List<ArgType> argTypes = Utils.collectionMap(methodProto.getArgTypes(), ArgType::parse);
107			List<ArgType> callTypes = new ArrayList<>(1 + argTypes.size());
108			callTypes.add(retType);
109			callTypes.addAll(argTypes);
110			ArgType mthType = ArgType.object("java.lang.invoke.MethodType");
111			ClassInfo cls = ClassInfo.fromType(root, mthType);
112			MethodInfo mth = MethodInfo.fromDetails(root, cls, "methodType", callTypes, mthType);
113			InvokeNode invoke = new InvokeNode(mth, InvokeType.STATIC, callTypes.size());
114			for (ArgType type : callTypes) {
115				InsnNode argInsn;
116				if (type.isPrimitive()) {
117					argInsn = new IndexInsnNode(InsnType.SGET, getTypeField(root, type.getPrimitiveType()), 0);
118				} else {
119					argInsn = new ConstClassNode(type);
120				}
121				invoke.addArg(InsnArg.wrapArg(argInsn));
122			}
123			return invoke;
124		}
125	
126		public static FieldInfo getTypeField(RootNode root, PrimitiveType type) {
127			ArgType boxType = type.getBoxType();
128			ClassInfo boxCls = ClassInfo.fromType(root, boxType);
129			return FieldInfo.from(root, boxCls, "TYPE", boxType);
130		}
131	
132		/**
133		 * Build `MethodHandles.lookup().find{type}(methodCls, methodName, methodType)`
134		 */
135		private static InsnNode buildMethodHandle(RootNode root, IMethodHandle methodHandle) {
136			if (methodHandle.getType().isField()) {
137				// TODO: lookup for field
138				return new ConstStringNode("FIELD:" + methodHandle.getFieldRef());
139			}
140			IMethodRef methodRef = methodHandle.getMethodRef();
141			methodRef.load();
142	
143			ClassInfo lookupCls = ClassInfo.fromName(root, "java.lang.invoke.MethodHandles.Lookup");
144			MethodInfo findMethod = MethodInfo.fromDetails(root, lookupCls,
145					getFindMethodName(methodHandle.getType()),
146					Arrays.asList(ArgType.CLASS, ArgType.STRING, ArgType.object("java.lang.invoke.MethodType")),
147					ArgType.object("java.lang.invoke.MethodHandle"));
148	
149			InvokeNode invoke = new InvokeNode(findMethod, InvokeType.DIRECT, 4);
150			invoke.addArg(buildLookupArg(root));
151			invoke.addArg(InsnArg.wrapArg(new ConstClassNode(ArgType.object(methodRef.getParentClassType()))));
152			invoke.addArg(InsnArg.wrapArg(new ConstStringNode(methodRef.getName())));
153			invoke.addArg(InsnArg.wrapArg(buildMethodType(root, methodRef)));
154			return invoke;
155		}
156	
157		public static InsnArg buildLookupArg(RootNode root) {
158			ArgType lookupType = ArgType.object("java.lang.invoke.MethodHandles.Lookup");
159			ClassInfo cls = ClassInfo.fromName(root, "java.lang.invoke.MethodHandles");
160			MethodInfo mth = MethodInfo.fromDetails(root, cls, "lookup", Collections.emptyList(), lookupType);
161			return InsnArg.wrapArg(new InvokeNode(mth, InvokeType.STATIC, 0));
162		}
163	
164		private static String getFindMethodName(MethodHandleType type) {
165			switch (type) {
166				case INVOKE_STATIC:
167					return "findStatic";
168				case INVOKE_CONSTRUCTOR:
169					return "findConstructor";
170				case INVOKE_INSTANCE:
171				case INVOKE_DIRECT:
172				case INVOKE_INTERFACE:
173					return "findVirtual";
174	
175				default:
176					return "<" + type + '>';
177			}
178		}
