112		void decodeTableChunk() throws IOException {
113			is.checkInt16(RES_TABLE_TYPE, "Not a table chunk");
114			is.checkInt16(0x000c, "Unexpected table header size");
115			int size = is.readInt32();
116			int pkgCount = is.readInt32();
117	
118			int pkgNum = 0;
119			while (is.getPos() < size) {
120				long chuckStart = is.getPos();
121				int type = is.readInt16();
122				int headerSize = is.readInt16();
123				long chunkSize = is.readUInt32();
124				long chunkEnd = chuckStart + chunkSize;
125				switch (type) {
126					case RES_NULL_TYPE:
127						// skip
128						break;
129	
130					case RES_STRING_POOL_TYPE:
131						strings = parseStringPoolNoSize(chuckStart, chunkEnd);
132						break;
133	
134					case RES_TABLE_PACKAGE_TYPE:
135						parsePackage(chuckStart, headerSize, chunkEnd);
136						pkgNum++;
137						break;
138				}
139				is.skipToPos(chunkEnd, "Skip to table chunk end");
140			}
141			if (pkgNum != pkgCount) {
142				LOG.warn("Unexpected package chunks, read: {}, expected: {}", pkgNum, pkgCount);
143			}
144		}
