146		private void parsePackage(long pkgChunkStart, int headerSize, long pkgChunkEnd) throws IOException {
147			if (headerSize < 0x011c) {
148				die("Package header size too small");
149				return;
150			}
151			int id = is.readInt32();
152			String name = is.readString16Fixed(128);
153			long typeStringsOffset = pkgChunkStart + is.readInt32();
154			int lastPublicType = is.readInt32();
155			long keyStringsOffset = pkgChunkStart + is.readInt32();
156			int lastPublicKey = is.readInt32();
157			if (headerSize >= 0x0120) {
158				int typeIdOffset = is.readInt32();
159			}
160			is.skipToPos(pkgChunkStart + headerSize, "package header end");
161	
162			BinaryXMLStrings typeStrings = null;
163			if (typeStringsOffset != 0) {
164				is.skipToPos(typeStringsOffset, "Expected typeStrings string pool");
165				typeStrings = parseStringPool();
166			}
167			BinaryXMLStrings keyStrings = null;
168			if (keyStringsOffset != 0) {
169				is.skipToPos(keyStringsOffset, "Expected keyStrings string pool");
170				keyStrings = parseStringPool();
171			}
172	
173			PackageChunk pkg = new PackageChunk(id, name, typeStrings, keyStrings);
174			resStorage.setAppPackage(name);
175	
176			while (is.getPos() < pkgChunkEnd) {
177				long chunkStart = is.getPos();
178				int type = is.readInt16();
179				LOG.trace("res package chunk start at {} type {}", chunkStart, type);
180				switch (type) {
181					case RES_NULL_TYPE:
182						LOG.info("Null chunk type encountered at offset {}", chunkStart);
183						break;
184					case RES_TABLE_TYPE_TYPE: // 0x0201
185						parseTypeChunk(chunkStart, pkg);
186						break;
187					case RES_TABLE_TYPE_SPEC_TYPE: // 0x0202
188						parseTypeSpecChunk(chunkStart);
189						break;
190					case RES_TABLE_TYPE_LIBRARY: // 0x0203
191						parseLibraryTypeChunk(chunkStart);
192						break;
193					case RES_TABLE_TYPE_OVERLAY: // 0x0204
194						parseOverlayTypeChunk(chunkStart);
195						break;
196					case RES_TABLE_TYPE_OVERLAY_POLICY: // 0x0205
197						throw new IOException(
198								String.format("Encountered unsupported chunk type RES_TABLE_TYPE_OVERLAY_POLICY at offset 0x%x ", chunkStart));
199					case RES_TABLE_TYPE_STAGED_ALIAS: // 0x0206
200						parseStagedAliasChunk(chunkStart);
201						break;
202					default:
203						LOG.warn("Unknown chunk type {} encountered at offset {}", type, chunkStart);
204				}
205			}
206		}
