244		/**
245		 * Parse an <code>ResTable_type</code> (except for the 2 bytes <code>uint16_t</code>
246		 * from <code>ResChunk_header</code>).
247		 * <p>
248		 * See: <a href=
249		 * "https://github.com/aosp-mirror/platform_frameworks_base/blob/master/libs/androidfw/include/androidfw/ResourceTypes.h">ResourceTypes.h</a>
250		 */
251		private void parseTypeChunk(long start, PackageChunk pkg) throws IOException {
252			/* int headerSize = */
253			is.readInt16();
254			/* int size = */
255			long chunkSize = is.readUInt32();
256			long chunkEnd = start + chunkSize;
257			is.mark(chunkSize);
258	
259			// The type identifier this chunk is holding. Type IDs start at 1 (corresponding
260			// to the value of the type bits in a resource identifier). 0 is invalid.
261			int typeId = is.readInt8();
262			String typeName = pkg.getTypeStrings().get(typeId - 1);
263	
264			int flags = is.readInt8();
265			boolean isSparse = (flags & FLAG_SPARSE) != 0;
266			boolean isOffset16 = (flags & FLAG_OFFSET16) != 0;
267	
268			is.readInt16(); // ignore reserved value - should be zero but in some apps it is not zero; see #2402
269			int entryCount = is.readInt32();
270			long entriesStart = start + is.readInt32();
271	
272			EntryConfig config = parseConfig();
273	
274			if (config.isInvalid) {
275				LOG.warn("Invalid config flags detected: {}{}", typeName, config.getQualifiers());
276			}
277	
278			List<EntryOffset> offsets = new ArrayList<>(entryCount);
279			if (isSparse) {
280				for (int i = 0; i < entryCount; i++) {
281					int idx = is.readInt16();
282					int offset = is.readInt16() * 4; // The offset in ResTable_sparseTypeEntry::offset is stored divided by 4.
283					offsets.add(new EntryOffset(idx, offset));
284				}
285			} else if (isOffset16) {
286				for (int i = 0; i < entryCount; i++) {
287					int offset = is.readInt16();
288					if (offset != 0xFFFF) {
289						offsets.add(new EntryOffset(i, offset * 4));
290					}
291				}
292			} else {
293				for (int i = 0; i < entryCount; i++) {
294					offsets.add(new EntryOffset(i, is.readInt32()));
295				}
296			}
297			is.skipToPos(entriesStart, "Failed to skip to entries start");
298			int ignoredEoc = 0; // ignored entries because they are located after end of chunk
299			Set<Integer> processedIndices = new HashSet<>(offsets.size() * 2);

300			for (EntryOffset entryOffset : offsets) {
301				int offset = entryOffset.getOffset();
302				if (offset == NO_ENTRY) {
303					continue;
304				}
305				int index = entryOffset.getIdx();
306				if (isSparse && !processedIndices.add(index)) {
307					// Sometimes sparse type chunks contain multiple entries with the same index.
308					// If we have processed the index once, we assume can ignore other entries with the same index.
309					continue;
310				}
311				long entryStartOffset = entriesStart + offset;
312				if (entryStartOffset >= chunkEnd) {
313					// Certain resource obfuscated apps like com.facebook.orca have more entries defined
314					// than actually fit into the chunk size -> ignore this entry
315					ignoredEoc++;
316					// LOG.debug("Pos is after chunk end: {} end {}", entryStartOffset, chunkEnd);
317					continue;
318				}
319				if (entryStartOffset < is.getPos()) {
320					// workaround for issue #2343: if the entryStartOffset is located before our current position
321					is.reset();
322				}
323				is.skipToPos(entryStartOffset, "Expected start of entry " + index);
324				parseEntry(pkg, typeId, index, config.getQualifiers());
325			}
326			if (ignoredEoc > 0) {
327				// invalid = data offset is after the chunk end
328				LOG.warn("{} entries of type {} has been ignored (invalid offset)", ignoredEoc, typeName);
329			}
330			is.skipToPos(chunkEnd, "End of chunk");
331		}
