361			// read ResTable_overlayable_header
362			/* headerSize = */
363			is.readInt16(); // usually 1032 bytes
364			int chunkSize = is.readInt32(); // e.g. 1056 bytes
365			long expectedEndPos = chunkStart + chunkSize;
366			String name = is.readString16Fixed(256); // 512 bytes
