373		private void parseStagedAliasChunk(long chunkStart) throws IOException {
374			// read ResTable_staged_alias_header
375			LOG.trace("parsing staged alias chunk starting at offset {}", chunkStart);
376			/* headerSize = */
377			is.readInt16();
378			int chunkSize = is.readInt32();
379			long expectedEndPos = chunkStart + chunkSize;
380			int count = is.readInt32();
381	
382			for (int i = 0; i < count; i++) {
383				// read ResTable_staged_alias_entry
384				int stagedResId = is.readInt32();
