391		private void parseEntry(PackageChunk pkg, int typeId, int entryId, String config) throws IOException {
392			int size = is.readInt16();
393			int flags = is.readInt16();
394			boolean isComplex = (flags & FLAG_COMPLEX) != 0;
395			boolean isCompact = (flags & FLAG_COMPACT) != 0;
396	
397			int key = isCompact ? size : is.readInt32();
398			if (key == -1) {
399				return;
400			}
401	
402			// resourceID as defined in AOSP make_resid()
403			int resId = pkg.getId() << 24 | typeId << 16 | entryId;
404			String typeName = pkg.getTypeStrings().get(typeId - 1);
405			String origKeyName = pkg.getKeyStrings().get(key);
406	
407			ResourceEntry newResEntry = buildResourceEntry(pkg, config, resId, typeName, origKeyName);
408			if (isCompact) {
409				int dataType = flags >> 8;
410				int data = is.readInt32();
411				newResEntry.setSimpleValue(new RawValue(dataType, data));
412			} else if (isComplex || size == 16) {
413				int parentRef = is.readInt32();
414				int count = is.readInt32();
415				newResEntry.setParentRef(parentRef);
416				List<RawNamedValue> values = new ArrayList<>(count);
417				for (int i = 0; i < count; i++) {
418					values.add(parseValueMap());
419				}
420				newResEntry.setNamedValues(values);
421			} else {
422				newResEntry.setSimpleValue(parseValue());
423			}
424		}
