18		protected BinaryXMLStrings parseStringPoolNoType() throws IOException {
19			long start = is.getPos() - 2;
20			int headerSize = is.readInt16();
21			if (headerSize != 0x1c) {
22				LOG.warn("Unexpected string pool header size: 0x{}, expected: 0x1C", Integer.toHexString(headerSize));
23			}
24			long size = is.readUInt32();
25			long chunkEnd = start + size;
26	
27			return parseStringPoolNoSize(start, chunkEnd);
28		}
29	
30		protected BinaryXMLStrings parseStringPoolNoSize(long start, long chunkEnd) throws IOException {
31			int stringCount = is.readInt32();
32			int styleCount = is.readInt32();
33			int flags = is.readInt32();
34			long stringsStart = is.readInt32();
35			long stylesStart = is.readInt32();
36	
37			// Correct the offset of actual strings, as the header is already read.
38			stringsStart = stringsStart - (is.getPos() - start);
39			byte[] buffer = is.readInt8Array((int) (chunkEnd - is.getPos()));
40			is.checkPos(chunkEnd, "Expected strings pool end");
41	
42			return new BinaryXMLStrings(
43					stringCount,
44					stringsStart,
45					buffer,
46					(flags & UTF8_FLAG) != 0);
47		}
