180			if (headerSize > 0x10) {
181				LOG.warn("Invalid namespace end");
182			} else if (headerSize < 0x10) {
183				die("NAMESPACE end is not 0x10 big");
184			}
185			int dataSize = is.readInt32();
186			if (dataSize != 0x18) {
187				LOG.warn("Invalid namespace end size");
188			}
189			int endLineNumber = is.readInt32();
190			int comment = is.readInt32();
191			int endPrefix = is.readInt32();
192			int endURI = is.readInt32();
193			is.skip(headerSize - 0x10);
194			namespaceDepth--;
